import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = reader.readLine().trim().split(" ");
        int total = Integer.parseInt(parts[0]);
        int front = Integer.parseInt(parts[1]);
        int back = Integer.parseInt(parts[2]);

        int diff = total - front;

        if (diff > back) {
            System.out.println(back + 1);
        } else {
            System.out.println(diff);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    private static String[] inputLines;
    private static int currentLine = 0;

    private static String readLine() {
        return inputLines[currentLine++];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder inputString = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            inputString.append(line).append("\n");
        }

        inputLines = inputString.toString().trim().split("\n");
        for (int i = 0; i < inputLines.length; i++) {
            inputLines[i] = inputLines[i].trim();
        }

        String[] parts = readLine().split(" ");
        int total = Integer.parseInt(parts[0]);
        int front = Integer.parseInt(parts[1]);
        int back = Integer.parseInt(parts[2]);

        int diff = total - front;

        if (diff > back) {
            System.out.println(back + 1);
        } else {
            System.out.println(diff);
        }
    }
}

